fn is_changed(some_text: String) -> bool {
    let mut last_line = "".to_string();

    // Split the string by new line to get lines.
    for line in some_text.split("\n") {
        // If we have a non-empty line, add it to the list of lines to compare with the previous one.
        if !line.is_empty() {
            let mut found_previous = false;

            // Check each line against the last one
            for current_line in last_line.split("\n") {
                if line.contains(current_line) {
                    found_previous = true;
                    break;
                }
            }

            // If no previous line matched, it's been changed.
            return !found_previous;
        }

        // Update last_line with the current line
        last_line.push_str(line);
    }

    false
}
```

